MOD = 10 ** 9 + 7

def f(a, b):
	if b == 1:
		return a % MOD
	elif b % 2 == 0:
		return f(a * a % MOD, b // 2)
	else:
		return a * f(a * a % MOD, b // 2) % MOD
(p, k) = map(int, input().split())
if k == 0:
	print(f(p, p - 1))
	exit()
if k == 1:
	print(f(p, p))
	exit()
t = 1
a = k
while a != 1:
	a = a * k % p
	t += 1
n = (p - 1) // t
print(f(p, n))
